    "definition": "(b. h.) Yah, abbreviation of the Tetragrammaton. Succ. IV, 5 (45ᵃ, missing in Ms. M., v. marginal note to ed.); Tosef. ib. III, 1 לַיָּהּ ולך מזבח unto Yah and unto thee, O altar (do we give praise); Succ. 45ᵇ ליה אנחנו מודים ולך וכ׳ to Yah we offer thanks and thee (altar) we praise. Ib. V, 4 (51ᵇ) אנו ליה וליה עינינו we are Yah’s and to Y. we lift up your eyes. Gen. R. s. 79, end, v. דְיָקִינְתִּ",
