    "pos": "unknown",
    "definition": "(b. h. כֹּה, v. preced.) adverb of place: here, v. הָכָא; of time: now. Targ. Gen. XXII, 5. Targ. Job XXXVIII, 11; a. fr.—Y. Ber. IV, 7ᶜ top וכא אמר הכין and here he says so? Ib. וכה; a. v. fr.—לְכָא hither; מִיכָּא from here. Targ. Josh. VIII, 20. Targ. Ex. XVII, 12; a. fr.—Y. Bets. V, 63ᵃ פצל … לכא ולכא skimmed the water in both directions. Y. B. Mets. VI, 11ᵃ top מיכא ללוד from here to Lydda; a",
