    "definition": "v. לַאי) not, no. Ber. I, 1 לא קרינו וכ׳ we have omitted to recite &c. Ib. III, 4 לא … ולא וכ׳ neither before nor after. Nidd. 5ᵃ לא אין להן וכ׳, no; it means &c., v. לַאו; a. v. fr.—וְלֹא indeed not? Ḥull. 4ᵇ ולא והכתיב וכ׳ indeed not (is it so that the verb הֵסִית never refers to persuasion by speech)? Do we not read &c.?; a. v. fr.—(מִצְוַת) לֹא תַעֲשֶׂה a prohibitory law, opp. עֲשֵׂה, a positi",
