    "definition": "לחח to be sticky, sappy, fresh) moist, green, fresh; liquid; opp. יבש. Dem. II, 3 לח ויבש either fresh or dried fruits. Ib. 5 ובלח דינר in selling fresh fruits (or liquids), a denar’s worth is wholesale; Y. ib. II, end, 23ᵃ נתנו דמים ללח וכ׳ for fresh fruit they adopt the standard of value, for dried that of quantity (cmp. לוּמָּא); Tosef. ib. III, 12 ובלח הין and for liquids the standard is a Hin",
