    "pos": "unknown",
    "definition": "what? Targ. O. Gen. XXXI, 26 ed. Berl. (mostly מָה, q. v.). מָא אִם, contr. מָאִים what (will happen) if?, suppose, perhaps. Targ. O. Gen. XVIII, 24 מא אם ed. Berl. (oth. ed. a. Y. מאים); a. fr.—מָא דֵין, contr. מָדֵין, מַדֵּין what is this?, why? Targ. I Kings I, 13 (מה) מא דין (ed. Lag. מדין; h. text מדוע). Targ. Jer. XII, 1. Targ. O. Gen. XL, 7 (some ed. מַה דֵּין); a. fr.",
