    "key": "עוז",
    "pos": "m.",
    "definition": "fortitude, strength, majesty. Ber. 6ᵃ התפלין ע׳ הם לישראל T’fillin are a sign of strength to Israel. Ex. R. s. 8 לבושו של הקב\"ה ע׳ the garment of the Lord is strength (with ref. to Ps. XCIII, 1). Midr. Till. to Ps. VIII, 3 אין ע׳ אלא תורה וכ׳ ‘strength’ means the Law, as we read (Ps. XXIX, 11) &c.; Mekh. B’shall., Shir., s. 3 אין עָוִּי וכ׳ ‘my strength’ (Ex. XV, 2) means &c. Ber. 16ᵇ תתכסה בעָזְּ",
